# 1 Corintios 14:40
texto1 = "Pero que todo se haga decentemente y con orden."
# Efesios 2:8
texto2 = "Porque por gracia han sido salvados, mediante la fe; y esto no procede de ustedes, pues es don de Dios,"

class Versiculo:
    def __init__(self, ref, texto):
        self.ref = ref
        self.texto = texto

    def palabras(self):
        return len(self.texto.split())


class Personaje:
    def __init__(self, nombre):
        self.nombre = nombre
        self.memorizados = []

    def memorizar(self, versiculo):
        self.memorizados.append(versiculo)

    def resumen(self):
        total = 0
        for v in self.memorizados:
            total += v.palabras()
        return f"{self.nombre} memorizó {len(self.memorizados)} versículos ({total} palabras)"


timoteo = Personaje("Timoteo")
timoteo.memorizar(Versiculo("1 Corintios 14:40", texto1))
timoteo.memorizar(Versiculo("Efesios 2:8", texto2))
for v in timoteo.memorizados:
    print(f"{v.ref}: {v.palabras()} palabras")
print(timoteo.resumen())

